"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { getRecentIdentities } from "@/lib/api/identities";
import { getObservations } from "@/lib/api/observations";
import { getAnomalies } from "@/lib/api/patterns";

import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";

import {
  ArrowRight,
  AlertTriangle,
  Eye,
  Users,
  TrendingUp,
} from "lucide-react";

/* ================= TYPES MATCH BACKEND ================= */

interface Identity {
  id: string;
  identityId: string;
  detectionCount: number;
  firstSeen: string;
  lastSeen: string;
  confidence: string;
}

interface Observation {
  id: string;
  identityId: string;
  cameraId: string;
  timestamp: string;
  imagePath: string;
}

interface Anomaly {
  id: string;
  identityId: string;
  cameraId: string;
  anomalyType: string;
  timestamp: string;
}

/* ====================================================== */

export default function AnalyticsPage() {
  const router = useRouter();

  const [recentIdentities, setRecentIdentities] = useState<Identity[]>([]);
  const [observationCount, setObservationCount] = useState(0);
  const [anomalyCount, setAnomalyCount] = useState(0);

  const [isLoading, setIsLoading] = useState(true);

  /* ================= FETCH DATA ================= */

  useEffect(() => {
    const fetchDashboardData = async () => {
      setIsLoading(true);

      try {
        const [identities, observations, anomalies] = await Promise.all([
          getRecentIdentities(),
          getObservations(),
          getAnomalies(),
        ]);

        setRecentIdentities(identities);
        setObservationCount(observations.length);
        setAnomalyCount(anomalies.length);
      } catch (error) {
        console.error("Error fetching analytics data:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchDashboardData();
  }, []);

  /* ================= CONFIDENCE BADGE ================= */

  const getConfidenceBadge = (confidence: string) => {
    const value = parseFloat(confidence);

    if (value >= 0.9) return "bg-green-500/20 text-green-400";
    if (value >= 0.7) return "bg-yellow-500/20 text-yellow-400";

    return "bg-red-500/20 text-red-400";
  };

  /* ================= UI ================= */

  return (
    <div className="space-y-6 p-6">
      {/* ================= METRICS ================= */}

      <div className="grid grid-cols-4 gap-4">
        <Card className="bg-[#222] border-[#333] p-6 hover:border-cyan-500/50 transition-colors">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-400">Total Observations</p>
              <p className="text-3xl font-bold text-white mt-2">
                {observationCount}
              </p>
            </div>

            <Eye size={32} className="text-cyan-400/30" />
          </div>
        </Card>

        <Card className="bg-[#222] border-[#333] p-6 hover:border-cyan-500/50 transition-colors">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-400">Detected Anomalies</p>
              <p className="text-3xl font-bold text-white mt-2">
                {anomalyCount}
              </p>
            </div>

            <AlertTriangle size={32} className="text-yellow-400/30" />
          </div>
        </Card>

        <Card className="bg-[#222] border-[#333] p-6 hover:border-cyan-500/50 transition-colors">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-400">Recent Identities</p>
              <p className="text-3xl font-bold text-white mt-2">
                {recentIdentities.length}
              </p>
            </div>

            <Users size={32} className="text-green-400/30" />
          </div>
        </Card>

        <Card className="bg-[#222] border-[#333] p-6 hover:border-cyan-500/50 transition-colors">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-400">Analytics</p>
              <p className="text-3xl font-bold text-white mt-2">ACTIVE</p>
            </div>

            <TrendingUp size={32} className="text-cyan-400/30" />
          </div>
        </Card>
      </div>

      {/* ================= RECENT IDENTITIES ================= */}

      <div>
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-bold text-white">
            Recently Detected Identities
          </h2>

          <button
            onClick={() => router.push("/analytics/identities")}
            className="flex items-center gap-2 px-4 py-2 text-sm text-cyan-400 hover:bg-cyan-500/10 rounded transition-colors"
          >
            View All
            <ArrowRight size={16} />
          </button>
        </div>

        {isLoading ? (
          <div className="space-y-2">
            {[...Array(3)].map((_, i) => (
              <Skeleton key={i} className="h-16 bg-[#333]" />
            ))}
          </div>
        ) : recentIdentities.length > 0 ? (
          <Card className="bg-[#222] border-[#333] overflow-hidden">
            <div className="divide-y divide-[#333]">
              {recentIdentities.map((identity) => (
                <div
                  key={identity.id}
                  className="p-4 hover:bg-[#333]/50 transition-colors cursor-pointer"
                  onClick={() =>
                    router.push(`/analytics/identities/${identity.id}`)
                  }
                >
                  <div className="flex items-center justify-between">
                    <div className="flex-1">
                      <p className="font-mono text-cyan-400">
                        {identity.identityId}
                      </p>

                      <p className="text-xs text-gray-400 mt-1">
                        {identity.detectionCount} detections
                      </p>
                    </div>

                    <Badge
                      className={`${getConfidenceBadge(identity.confidence)} border-0`}
                    >
                      {identity.confidence}
                    </Badge>
                  </div>
                </div>
              ))}
            </div>
          </Card>
        ) : (
          <Card className="bg-[#222] border-[#333] p-8 text-center">
            <p className="text-gray-400">No recent identities</p>
          </Card>
        )}
      </div>

      {/* ================= QUICK ACTIONS ================= */}

      <div>
        <h2 className="text-xl font-bold text-white mb-4">Quick Actions</h2>

        <div className="grid grid-cols-4 gap-4">
          <button
            onClick={() => router.push("/analytics/identities")}
            className="bg-[#222] border border-[#333] hover:border-cyan-500/50 rounded-lg p-4 text-left transition-colors"
          >
            <Users size={24} className="text-cyan-400 mb-2" />

            <p className="font-semibold text-white">Manage Identities</p>

            <p className="text-xs text-gray-400 mt-1">
              View and analyze detected identities
            </p>
          </button>

          <button
            onClick={() => router.push("/analytics/observations")}
            className="bg-[#222] border border-[#333] hover:border-cyan-500/50 rounded-lg p-4 text-left transition-colors"
          >
            <Eye size={24} className="text-cyan-400 mb-2" />

            <p className="font-semibold text-white">Monitor Observations</p>

            <p className="text-xs text-gray-400 mt-1">Track detection events</p>
          </button>

          <button
            onClick={() => router.push("/analytics/patterns")}
            className="bg-[#222] border border-[#333] hover:border-cyan-500/50 rounded-lg p-4 text-left transition-colors"
          >
            <TrendingUp size={24} className="text-cyan-400 mb-2" />

            <p className="font-semibold text-white">Analyze Patterns</p>

            <p className="text-xs text-gray-400 mt-1">
              Discover behavior patterns
            </p>
          </button>

          <button
            onClick={() => router.push("/analytics/anomalies")}
            className="bg-[#222] border border-[#333] hover:border-cyan-500/50 rounded-lg p-4 text-left transition-colors"
          >
            <AlertTriangle size={24} className="text-cyan-400 mb-2" />

            <p className="font-semibold text-white">Review Anomalies</p>

            <p className="text-xs text-gray-400 mt-1">
              Investigate suspicious activity
            </p>
          </button>
        </div>
      </div>
    </div>
  );
}
