const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:5000";

/* ================= TYPES ================= */

export interface Identity {
  id: string; // Mongo ObjectId
  identityId: string; // Business ID (e.g. ID_34)

  detectionCount: number;
  firstSeen: string;
  lastSeen: string;

  confidence: string;
  consistency: number;
}

export interface IdentityTimeline {
  id: string;
  identityId: string;
  cameraId: string;

  timestamp: string;
  imagePath: string;
}

interface ApiResponse<T> {
  success: boolean;
  data: T;
  count?: number;
}

/* ================= GET ALL IDENTITIES ================= */

export async function getIdentities(): Promise<Identity[]> {
  try {
    const response = await fetch(`${API_BASE_URL}/api/identities`, {
      cache: "no-store",
      credentials: "include",
    });

    const data: ApiResponse<Identity[]> = await response.json();

    return data.success ? data.data : [];
  } catch (error) {
    console.error("Failed to fetch identities:", error);
    return [];
  }
}

